 law.', q.options = '[{"prefix": "A", "content": "emphasize", "itemUuid": "cloze-english1-real-2012-1-A"}, {"prefix": "B", "content": "maintain", "itemUuid": "cloze-english1-real-2012-1-B"}, {"prefix": "C", "content": "modify", "itemUuid": "cloze-english1-real-2012-1-C"}, {"prefix": "D", "content": "recognize", "itemUuid": "cloze-english1-real-2012-1-D"}]' WHERE q.subject_id = 9 AND q.source_year = 2012 AND q.source_question_no = 1 AND q.deleted = b'0';
