UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2015/q1-title.html" data-fallback="We have more genes in common with people we pick to be our friends than with strangers. Though not biologically related, friends are as “related” as fourth cousins, sharing about 1"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "when", "itemUuid": "cloze-english1-real-2015-1-A"}, {"prefix": "B", "content": "why", "itemUuid": "cloze-english1-real-2015-1-B"}, {"prefix": "C", "content": "how", "itemUuid": "cloze-english1-real-2015-1-C"}, {"prefix": "D", "content": "what", "itemUuid": "cloze-english1-real-2015-1-D"}]' AS JSON)) WHERE q.subject_id = 9 AND q.source_year = 2015 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2015/q1-title.html" data-fallback="We have more genes in common with people we pick to be our friends than with strangers. Though not biologically related, friends are as “related” as fourth cousins, sharing about 1"></div>', q.title_text = 'We have more genes in common with people we pick to be our friends than with strangers. Though not biologically related, friends are as “related” as fourth cousins, sharing about 1% of genes. That is 1 ​ a study published from the University of California and Yale University in the Proceedings of the National Academy of Sciences has 2 ​ . The study is a genome - wide analysis conducted 3 ​ 1932 unique subjects which 4 ​ pairs of unrelated friends and unrelated strangers. The same people were used in both 5 ​ . While 1% may seem 6 ​ , it is not so to a geneticist. As co - author of the study James Fowler, professor of medical genetics at UC San Diego says, “Most people do not even 7 ​ their fourth cousins but somehow manage to select as friends the people who 8 ​ our kin.” The team 9 ​ developed a “friendship score” which can predict who will be your friend based on their genes. The study also found that the genes for smell were something shared in friends but not genes for immunity. Why this similarity in olfactory genes is difficult to explain, for now. 10 ​ , as the team suggests, it draws us 11 ​ similar environments but there is more to it. There could be many mechanisms working in tandem that 12 ​ us in choosing genetically similar friends 13 ​ “functional kinship” of being friends with 14 ​ ! One of the remarkable findings of the study was that the similar genes seem to be evolving 15 ​ than other genes. Studying this could help 16 ​ why human evolution picked pace in the last 30, 000 years, with social environment being a major 17 ​ factor. The findings do not simply corroborate people’s 18 ​ to befriend those of similar et 19 ​ backgrounds, say the researchers. Though all the subjects were drawn from a population of European extraction, care was taken to 20 ​ that all subjects, friends and strangers were taken from the same population. The team also controlled the data to check ancestry of subjects.', q.options = '[{"prefix": "A", "content": "when", "itemUuid": "cloze-english1-real-2015-1-A"}, {"prefix": "B", "content": "why", "itemUuid": "cloze-english1-real-2015-1-B"}, {"prefix": "C", "content": "how", "itemUuid": "cloze-english1-real-2015-1-C"}, {"prefix": "D", "content": "what", "itemUuid": "cloze-english1-real-2015-1-D"}]' WHERE q.subject_id = 9 AND q.source_year = 2015 AND q.source_question_no = 1 AND q.deleted = b'0';
