UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2017/q1-title.html" data-fallback="Could a hug a day keep the doctor away? The answer may be a resounding “yes!” 1 ​ helping you feel close and 2 ​ to people you care about, it turns out that hugs can bring a 3 ​ of"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "Unlike", "itemUuid": "cloze-english1-real-2017-1-A"}, {"prefix": "B", "content": "Besides", "itemUuid": "cloze-english1-real-2017-1-B"}, {"prefix": "C", "content": "Throughout", "itemUuid": "cloze-english1-real-2017-1-C"}, {"prefix": "D", "content": "Despite", "itemUuid": "cloze-english1-real-2017-1-D"}]' AS JSON)) WHERE q.subject_id = 9 AND q.source_year = 2017 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2017/q1-title.html" data-fallback="Could a hug a day keep the doctor away? The answer may be a resounding “yes!” 1 ​ helping you feel close and 2 ​ to people you care about, it turns out that hugs can bring a 3 ​ of"></div>', q.title_text = 'Could a hug a day keep the doctor away? The answer may be a resounding “yes!” 1 ​ helping you feel close and 2 ​ to people you care about, it turns out that hugs can bring a 3 ​ of health benefits to your body and mind. Believe it or not, a warm embrace might even help you 4 ​ getting sick this winter. In a recent study 5 ​ over 400 healthy adults, researchers from Carnegie Mellon University in Pennsylvania examined the effects of perceived social support and the receipt of hugs 6 ​ the participants’ susceptibility to developing the common cold after being 7 ​ to the virus. People who perceived greater social support were less likely to come 8 ​ with a cold, and the researchers 9 ​ that the stress - reducing effects of hugging 10 ​ about 32 percent of that beneficial effect. 11 ​ among those who got a cold, the ones who felt greater social support and received more frequent hugs had less severe 12 ​ . “Hugging protects people who are under stress from the 13 ​ risk for colds that’s usually 14 ​ with stress,” notes Sheldon Cohen, a professor of psychology at Carnegie. Hugging “is a marker of intimacy and helps 15 ​ the feeling that others are there to help 16 ​ difficulty.” Some experts 17 ​ the stress - reducing, health - related benefits of hugging to the release of oxytocin, often called “the bonding hormone” 18 ​ it promotes attachment in relationships, including that between mothers and their newborn babies. Oxytocin is made primarily in the central lower part of the brain, and some of it is released into the bloodstream. But some of it 19 ​ in the brain, where it 20 ​ mood, behavior and physiology. 每天一个拥抱真的能让人不生病吗？答案或许是响亮的“是的！”除了能让你感觉与关心的人更亲密、联系更紧密之外，事实证明拥抱还能为你的身心带来诸多健康益处。信不信由你，一个温暖的拥抱甚至可能帮助你这个冬天不生病。 在最近一项针对400多名健康成年人的研究中，宾夕法尼亚州卡内基梅隆大学的研究人员考察了感知到的社会支持以及接受拥抱对参与者暴露于病毒后患普通感冒的易感性的影响。那些感知到更多社会支持的人患感冒的几率较低，研究人员认为拥抱的减压效果带来了约32%的这种益处。即使那些感冒的人中，感受到更多社会支持且接受拥抱更频繁的人症状也较轻。 卡内基梅隆大学心理学教授谢尔登·科恩指出：“拥抱能保护处于压力下的人免受通常与压力相关的感冒风险增加的影响。”拥抱是“亲密关系的标志，有助于强化一种感觉，即在困难时有人会提供帮助。” 一些专家将拥抱减压及与健康相关的益处归因于催产素的释放。催产素常被称为“亲密激素”，因为它能促进人际关系中的依恋，包括母亲与新生儿之间的情感。催产素主要在大脑中枢下部产生，一部分会释放到血液中，但还有一部分会留在大脑中，影响情绪、行为和生理机能。', q.options = '[{"prefix": "A", "content": "Unlike", "itemUuid": "cloze-english1-real-2017-1-A"}, {"prefix": "B", "content": "Besides", "itemUuid": "cloze-english1-real-2017-1-B"}, {"prefix": "C", "content": "Throughout", "itemUuid": "cloze-english1-real-2017-1-C"}, {"prefix": "D", "content": "Despite", "itemUuid": "cloze-english1-real-2017-1-D"}]' WHERE q.subject_id = 9 AND q.source_year = 2017 AND q.source_question_no = 1 AND q.deleted = b'0';
