UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2019/q1-title.html" data-fallback="Today we live in a world where GPS systems, digital maps, and other navigation apps are available on our smartphones. 1 ​ of us just walk straight into the woods without a phone. B"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "Some", "itemUuid": "cloze-english1-real-2019-1-A"}, {"prefix": "B", "content": "Most", "itemUuid": "cloze-english1-real-2019-1-B"}, {"prefix": "C", "content": "Few", "itemUuid": "cloze-english1-real-2019-1-C"}, {"prefix": "D", "content": "All", "itemUuid": "cloze-english1-real-2019-1-D"}]' AS JSON)) WHERE q.subject_id = 9 AND q.source_year = 2019 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2019/q1-title.html" data-fallback="Today we live in a world where GPS systems, digital maps, and other navigation apps are available on our smartphones. 1 ​ of us just walk straight into the woods without a phone. B"></div>', q.title_text = 'Today we live in a world where GPS systems, digital maps, and other navigation apps are available on our smartphones. 1 ​ of us just walk straight into the woods without a phone. But phones 2 ​ on batteries, and batteries can die faster than we realize. 3 ​ you get lost without a phone or a compass, and you 4 ​ can’t find north, we have a few tricks to help you navigate 5 ​ to civilization, one of which is to follow the land. When you find yourself well 6 ​ a trail, but not in a completely 7 ​ area, you have to answer two questions: Which 8 ​ is downhill, in this particular area? And where is the nearest water source? Humans overwhelmingly live in valleys, and on supplies of fresh water. 9 ​ , if you head downhill, and follow any H20 you find, you should 10 ​ see signs of people. If you’ve explored the area before, keep an eye out for familiar sights - you may be 11 ​ how quickly identifying a distinctive rock or tree can restore your bearings. Another 12 ​ : Climb high and look for signs of human habitation. 13 ​ even in dense forest, you should be able to 14 ​ gaps in the tree line due to roads, train tracks, and other paths people carve 15 ​ the woods. Head toward these 16 ​ to find a way out. At night, scan the horizon for 17 ​ light sources, such as fires and streetlights, then walk toward the glow of light pollution. 18 ​ , assuming you’re lost in an area humans tend to frequent, look for the 19 ​ we leave on the landscape. Trail blazes, tire tracks, and other features can 20 ​ you to civilization. 如今，我们生活在一个GPS系统、数字地图和其他导航应用都能在智能手机上使用的世界。我们中很少有人会不带手机就径直走进森林。但手机依赖电池，而电池的消耗速度可能比我们意识到的更快。如果你在没有手机或指南针的情况下迷路了，而且完全找不到北方，我们有一些技巧可以帮助你导航回到文明世界，其中之一就是顺着地形走。 当你发现自己偏离了小径，但并非完全在陌生区域时，你必须回答两个问题：在这个特定区域，哪个方向是下坡？最近的水源在哪里？人类绝大多数生活在山谷中，并依赖淡水供应。因此，如果你往山下走，并沿着发现的任何水源前进，你应该能看到人类的踪迹。 如果你之前探索过这个区域，请留意熟悉的景象——你可能会惊讶地发现，辨认出一块独特的岩石或一棵树能多快地恢复你的方向感。 另一个建议：爬到高处，寻找人类居住的痕迹。即使在茂密的森林中，你也应该能够察觉到树木线因道路、铁轨和其他人类开辟的小径而出现的空隙。朝这些空隙方向前进，找到出路。夜晚时，扫视地平线寻找人造光源，例如火光和路灯，然后朝着光污染的光亮方向走。 最后，假设你迷失在人类常活动的区域，留意我们在景观上留下的痕迹。小径标记、轮胎印和其他特征可以引导你回到文明世界。', q.options = '[{"prefix": "A", "content": "Some", "itemUuid": "cloze-english1-real-2019-1-A"}, {"prefix": "B", "content": "Most", "itemUuid": "cloze-english1-real-2019-1-B"}, {"prefix": "C", "content": "Few", "itemUuid": "cloze-english1-real-2019-1-C"}, {"prefix": "D", "content": "All", "itemUuid": "cloze-english1-real-2019-1-D"}]' WHERE q.subject_id = 9 AND q.source_year = 2019 AND q.source_question_no = 1 AND q.deleted = b'0';
