UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2022/q1-title.html" data-fallback="The idea that plants have some degree of consciousness first took root in the early 2000s; the term “plant neurobiology” was 1 ​ around the notion that some aspects of plant behavi"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "coined", "itemUuid": "cloze-english1-real-2022-1-A"}, {"prefix": "B", "content": "discovered", "itemUuid": "cloze-english1-real-2022-1-B"}, {"prefix": "C", "content": "collected", "itemUuid": "cloze-english1-real-2022-1-C"}, {"prefix": "D", "content": "issued", "itemUuid": "cloze-english1-real-2022-1-D"}]' AS JSON)) WHERE q.subject_id = 9 AND q.source_year = 2022 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2022/q1-title.html" data-fallback="The idea that plants have some degree of consciousness first took root in the early 2000s; the term “plant neurobiology” was 1 ​ around the notion that some aspects of plant behavi"></div>', q.title_text = 'The idea that plants have some degree of consciousness first took root in the early 2000s; the term “plant neurobiology” was 1 ​ around the notion that some aspects of plant behavior could be 2 ​ to intelligence in animals. 3 ​ plants lack brains, the firing of electrical signals in their stems and leaves nonetheless triggered responses that 4 ​ consciousness, researchers previously reported. But such an idea is untrue, according to a new opinion article. Plant biology is complex and fascinating, but it 5 ​ so greatly from that of animals that so-called 6 ​ of plants’ intelligence is inconclusive, the authors wrote. Beginning in 2006, some scientists have 7 ​ that plants possess neuron-like cells that interact with hormones and neurotransmitters, 8 ​ “a plant nervous system, 9 9 ​ to that in animals,” said lead study author Lincoln Taiz. “They 10 ​ claimed that plants have ‘brain-like command centers’ at their root tips.” This 11 ​ makes sense if you simplify the workings of a complex brain, 12 ​ it to an array of electrical pulses; cells in plants also communicate through electrical signals. 13 ​ , the signaling in a plant is only 14 ​ similar to the firing in a complex animal brain, which is more than “a mass of cells that communicate by electricity,” Taiz said. “For consciousness to evolve, a brain with a threshold 15 ​ of complexity and capacity is required,” he 16 ​ . “Since plants don’t have nervous systems, the 17 ​ that they have consciousness are effectively zero.” And what’s so great about consciousness, anyway? Plants can’t run away from 18 ​ , so investing energy in a body system which 19 ​ a threat and can feel pain would be a very 20 ​ evolutionary strategy, according to the article.', q.options = '[{"prefix": "A", "content": "coined", "itemUuid": "cloze-english1-real-2022-1-A"}, {"prefix": "B", "content": "discovered", "itemUuid": "cloze-english1-real-2022-1-B"}, {"prefix": "C", "content": "collected", "itemUuid": "cloze-english1-real-2022-1-C"}, {"prefix": "D", "content": "issued", "itemUuid": "cloze-english1-real-2022-1-D"}]' WHERE q.subject_id = 9 AND q.source_year = 2022 AND q.source_question_no = 1 AND q.deleted = b'0';
