UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2023/q1-title.html" data-fallback="Caravanserais were roadside inns that were built along the Silk Road in areas including China, North Africa and the Middle East. They were typically 1 ​ outside the walls of a city"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "displayed", "itemUuid": "cloze-english1-real-2023-1-A"}, {"prefix": "B", "content": "occupied", "itemUuid": "cloze-english1-real-2023-1-B"}, {"prefix": "C", "content": "located", "itemUuid": "cloze-english1-real-2023-1-C"}, {"prefix": "D", "content": "equipped", "itemUuid": "cloze-english1-real-2023-1-D"}]' AS JSON)) WHERE q.subject_id = 9 AND q.source_year = 2023 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english1-real-2023/q1-title.html" data-fallback="Caravanserais were roadside inns that were built along the Silk Road in areas including China, North Africa and the Middle East. They were typically 1 ​ outside the walls of a city"></div>', q.title_text = 'Caravanserais were roadside inns that were built along the Silk Road in areas including China, North Africa and the Middle East. They were typically 1 ​ outside the walls of a city or village and were usually funded by governments or 2 ​ . This word " Caravanserais" is 3 ​ a of the Persian word " karv:an" , which means a group of ltravellers or a caravan , and " seray " , a palace or enclosed building. The term caravan was used to 4 ​ groups of people who travelled together across the ancient network for safety reasons , 5 ​ merchants, travellers or pillgrims. From the 10th century onwards, as merchant and travel routes became more developed,the 6 ​ of the caravanserais increased and they served as a more developed, the 6 ​ of the caravanserais increased and they served as a safe place for people to :rest at night. Travellers on the Silk Road 7 ​ possibility of being attacked by thieves or being 8 ​ to extreme weather conditions. For this reason, caravanserais were strategically placed 9 ​ they could be reached in a day’s travel time. Caravanserais served as an informal 10 ​ point for the various people who travelled the Silk Road. 11 ​ , these structures became important centers for cultural 12 ​ and interaction, with travellers sharing their cultures, ideas and beliefs, 13 ​ taking knowledge with them, greatly 14 ​ the development of several civilisations. Caravanserais were also an important marketplace for commodities and 15 ​ in the trade of goods along the Silk Road. 16 ​ , it was frequently the first stop for merchants looking to sell their wares and 17 ​ supplies for their own journeys. It is 18 ​ that around 12,000 to 15,000 caravanserais were built along the Silk Road, 19 ​ only about 3 , 000 are known to remain today , many of which are in 20 ​ .', q.options = '[{"prefix": "A", "content": "displayed", "itemUuid": "cloze-english1-real-2023-1-A"}, {"prefix": "B", "content": "occupied", "itemUuid": "cloze-english1-real-2023-1-B"}, {"prefix": "C", "content": "located", "itemUuid": "cloze-english1-real-2023-1-C"}, {"prefix": "D", "content": "equipped", "itemUuid": "cloze-english1-real-2023-1-D"}]' WHERE q.subject_id = 9 AND q.source_year = 2023 AND q.source_question_no = 1 AND q.deleted = b'0';
