UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2011/q1-title.html" data-fallback="The Internet affords anonymity to its users, a blessing to privacy and freedom of speech. But that very anonymity is also behind the explosion of cyber-crime that has 1 ​ across th"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "swept", "itemUuid": "cloze-english2-real-2011-1-A"}, {"prefix": "B", "content": "skipped", "itemUuid": "cloze-english2-real-2011-1-B"}, {"prefix": "C", "content": "walked", "itemUuid": "cloze-english2-real-2011-1-C"}, {"prefix": "D", "content": "ridden", "itemUuid": "cloze-english2-real-2011-1-D"}]' AS JSON)) WHERE q.subject_id = 10 AND q.source_year = 2011 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2011/q1-title.html" data-fallback="The Internet affords anonymity to its users, a blessing to privacy and freedom of speech. But that very anonymity is also behind the explosion of cyber-crime that has 1 ​ across th"></div>', q.title_text = 'The Internet affords anonymity to its users, a blessing to privacy and freedom of speech. But that very anonymity is also behind the explosion of cyber-crime that has 1 ​ across the Web. Can privacy be preserved 2 ​ bringing safety and security to a world that seems increasingly 3 ​ ? Last month, Howard Schmidt, the nation’s cyber-czar, offered the federal government a 4 ​ to make the Web a safer place-a “voluntary trusted identity” system that would be the high-tech 5 ​ of a physical key, a fingerprint and a photo ID card, all rolled 6 ​ one. The system might use a smart identity card, or a digital credential 7 ​ to a specific computer .and would authenticate users at a range of online services. The idea is to 8 ​ a federation of private online identity systems. User could 9 ​ which system to join, and only registered users whose identities have been authenticated could navigate those systems. The approach contrasts with one that would require an Internet driver’s license 10 ​ by the government. Google and Microsoft are among companies that already have these “single sign-on” systems that make it possible for users to 11 ​ just once but use many different services. 12 ​ , the approach would create a “walled garden” in cyberspace, with safe “neighborhoods” and bright “streetlights” to establish a sense of a 13 ​ community. Mr. Schmidt described it as a “voluntary ecosystem” in which “individuals and organizations can complete online transactions with 14 ​ , trusting the identities of each other and the identities of the infrastructure 15 ​ which the transaction runs”. Still, the administration’s plan has 16 ​ privacy rights activists. Some applaud the approach; others are concerned. It seems clear that such a scheme is an initiative push toward what would 17 ​ be a compulsory Internet “drive’s license” mentality. The plan has also been greeted with 18 ​ by some computer security experts, who worry that the “voluntary ecosystem” envisioned by Mr. Schmidt would still leave much of the Internet 19 ​ .They argue that all Internet users should be 20 ​ to register and identify themselves, in the same way that drivers must be licensed to drive on public roads.', q.options = '[{"prefix": "A", "content": "swept", "itemUuid": "cloze-english2-real-2011-1-A"}, {"prefix": "B", "content": "skipped", "itemUuid": "cloze-english2-real-2011-1-B"}, {"prefix": "C", "content": "walked", "itemUuid": "cloze-english2-real-2011-1-C"}, {"prefix": "D", "content": "ridden", "itemUuid": "cloze-english2-real-2011-1-D"}]' WHERE q.subject_id = 10 AND q.source_year = 2011 AND q.source_question_no = 1 AND q.deleted = b'0';
