UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2012/q1-title.html" data-fallback="Millions of Americans and foreigners see G.I. Joe as a mindless war toy, the symbol of American military adventurism, but that’s not how it used to be. To the men and women who 1 ​"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "served", "itemUuid": "cloze-english2-real-2012-1-A"}, {"prefix": "B", "content": "performed", "itemUuid": "cloze-english2-real-2012-1-B"}, {"prefix": "C", "content": "rebelled", "itemUuid": "cloze-english2-real-2012-1-C"}, {"prefix": "D", "content": "betrayed", "itemUuid": "cloze-english2-real-2012-1-D"}]' AS JSON)) WHERE q.subject_id = 10 AND q.source_year = 2012 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2012/q1-title.html" data-fallback="Millions of Americans and foreigners see G.I. Joe as a mindless war toy, the symbol of American military adventurism, but that’s not how it used to be. To the men and women who 1 ​"></div>', q.title_text = 'Millions of Americans and foreigners see G.I. Joe as a mindless war toy, the symbol of American military adventurism, but that’s not how it used to be. To the men and women who 1 ​ in World War II and the people they liberated, the G.I. was the 2 ​ man grown into hero, the poor farm kid torn away from his home, the guy who 3 ​ all the burdens of battle, who slept in cold foxholes, who went without the 4 ​ of food and shelter, who stuck it out and drove back the Nazi reign of murder. This was not a volunteer soldier, not someone well paid, 5 ​ an average guy, up 6 ​ the best trained, best equipped, fiercest, most brutal enemies in centuries. His name isn’t much. G.I. is just a military abbreviation 7 ​ Government Issue, and it was on all of the articles 8 ​ to soldiers. And Joe? A common name for a guy who never 9 ​ it to the top. Joe Blow, Joe Palooka, Joe Magrac…a working class name. The United States has 10 ​ had a president or vice-president or secretary of state Joe. G.I. Joe had a 11 ​ career fighting German, Japanese, and Korean troops. He appears as a character, or a 12 ​ of American personalities, in the 1945 movie The Story of G.I. Joe, based on the last days of war correspondent Ernie Pyle. Some of the soldiers Pyle 13 ​ portrayed themselves in the film. Pyle was famous for covering the 14 ​ side of the war, writing about the dirt-snow-and-mud soldiers, not how many miles were 15 ​ or what towns were captured or liberated. His reports 16 ​ the “Willie” cartoons of famed Stars and Stripes artist Bill Mauldin. Both men 17 ​ the dirt and exhaustion of war, the 18 ​ of civilization that the soldiers shared with each other and the civilians: coffee, tobacco, whiskey, shelter, sleep. 19 ​ Egypt, France, and a dozen more countries, G.I. Joe was any American soldier, 20 ​ the most important person in their lives.', q.options = '[{"prefix": "A", "content": "served", "itemUuid": "cloze-english2-real-2012-1-A"}, {"prefix": "B", "content": "performed", "itemUuid": "cloze-english2-real-2012-1-B"}, {"prefix": "C", "content": "rebelled", "itemUuid": "cloze-english2-real-2012-1-C"}, {"prefix": "D", "content": "betrayed", "itemUuid": "cloze-english2-real-2012-1-D"}]' WHERE q.subject_id = 10 AND q.source_year = 2012 AND q.source_question_no = 1 AND q.deleted = b'0';
