UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2015/q1-title.html" data-fallback="In our contemporary culture,the prospect of communicating with– or even looking at–a stranger is virtually unbearable. Everyone around us seems to agree by the way they fiddle with"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "signal", "itemUuid": "cloze-english2-real-2015-1-A"}, {"prefix": "B", "content": "permit", "itemUuid": "cloze-english2-real-2015-1-B"}, {"prefix": "C", "content": "ticket", "itemUuid": "cloze-english2-real-2015-1-C"}, {"prefix": "D", "content": "record", "itemUuid": "cloze-english2-real-2015-1-D"}]' AS JSON)) WHERE q.subject_id = 10 AND q.source_year = 2015 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2015/q1-title.html" data-fallback="In our contemporary culture,the prospect of communicating with– or even looking at–a stranger is virtually unbearable. Everyone around us seems to agree by the way they fiddle with"></div>', q.title_text = 'In our contemporary culture,the prospect of communicating with– or even looking at–a stranger is virtually unbearable. Everyone around us seems to agree by the way they fiddle with their phones,even without a 1 ​ underground. It’s a sad reality – our desire to avoid interacting with other human beings – because there’s 2 ​ to be gained from talking to the stranger standing by you. But you wouldn’t know it, 3 ​ into your phone.This universal armor sends the 4 ​ :“Please don’t approach me.” What is it that makes us feel we need to hide 5 ​ our screens? One answer is fear,according to Jon Wortmann, executive mental coach. We fear rejection, or that our innocent social advances will be 6 ​ as “creepy,".We fear we''11 be 7 ​ .We fear we''11 be disruptive. Strangers are inherently 8 ​ to us, so we are more likely to feel 9 ​ when communicating with them compared with our friends and acquaintances.To avoid this anxiety, we 10 ​ to our phones. “Phones become our security blanket,“Wortmann says.“They are our happy glasses that protect us from what we perceive is going to be more 11 ​ .” But once we rip off the bandaid, tuck our smartphones in our pockets and look up, it doesn’t 12 ​ so bad.In one 2011 experiment,behavioral scientists Nicholas Epley and Juliana Schroeder asked commuters to do the unthinkable: Start a 13 ​ .They had Chicago train commuters talk to their fellow 14 ​ .“When Dr.Epley and Ms. Schroeder asked other people in the same train station to 15 ​ how they would feel after talking to a stranger,the commuters thought their 16 ​ would be more pleasant if they sat on their own,” the New York Times summarizes. Though the participants didn’t expect a positive experience,after they 17 ​ with the experiment,“not a single person reported having been snubbed.', q.options = '[{"prefix": "A", "content": "signal", "itemUuid": "cloze-english2-real-2015-1-A"}, {"prefix": "B", "content": "permit", "itemUuid": "cloze-english2-real-2015-1-B"}, {"prefix": "C", "content": "ticket", "itemUuid": "cloze-english2-real-2015-1-C"}, {"prefix": "D", "content": "record", "itemUuid": "cloze-english2-real-2015-1-D"}]' WHERE q.subject_id = 10 AND q.source_year = 2015 AND q.source_question_no = 1 AND q.deleted = b'0';
