UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2020/q1-title.html" data-fallback="Being a good parent is what every parent would like to be. But defining what it means to be a good parent is undoubtedly very 1 ​ , particularly since children respond differently "></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "tedious", "itemUuid": "cloze-english2-real-2020-1-A"}, {"prefix": "B", "content": "pleasant", "itemUuid": "cloze-english2-real-2020-1-B"}, {"prefix": "C", "content": "instructive", "itemUuid": "cloze-english2-real-2020-1-C"}, {"prefix": "D", "content": "tricky", "itemUuid": "cloze-english2-real-2020-1-D"}]' AS JSON)) WHERE q.subject_id = 10 AND q.source_year = 2020 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2020/q1-title.html" data-fallback="Being a good parent is what every parent would like to be. But defining what it means to be a good parent is undoubtedly very 1 ​ , particularly since children respond differently "></div>', q.title_text = 'Being a good parent is what every parent would like to be. But defining what it means to be a good parent is undoubtedly very 1 ​ , particularly since children respond differently to the same style. of parenting. A calm, rule-following child might respond better to a different sort of parenting than, 2 ​ , a younger one. 3 ​ , there’s another sort of parent that’s easier to 4 ​ : a parent. Children of every age benefit from patient parenting. Still, 2 ​ , every parent would like to be patient, this is no easy 6 ​ , sometimes, parents get exhausted and are unable to maintain a 7 ​ style with their kids. I understand this. You’re only human, and sometimes your kids can 8 ​ you just a little too far. And then the 9 ​ happens: You lose your patience and either scream at your kids or say something that was too 10 ​ and does nobody any good.:You wish that you could 11 ​ the clock and start over. We’ve all been there. 12 ​ , even though it’s common, its vital to keep in mind that in a single moment of fatigue, you can say something to your child that you may 13 ​ for a long time, This may not only do damage to your relationship with your child but also 14 ​ your child’s self-esteem. If you consistently lose your 15 ​ with your kids, then you are modeling a lack of emotional control for your kids. We are all becoming increasingly aware of the 16 ​ of modeling patience for the younger generation. This is a skill that will help them all throughout life. In fact, the ability to maintain emotional control when 17 ​ by stress is one of the most significant of all life’s skills. Certainly, it’s 18 ​ to maintain patience at all times with your kids, A more practical goal is to try to be as calm as you can when faced with 19 ​ situations involving your children. I can promise you this: As a result of working toward this goal, you and your children will benefit and, 20 ​ from stressful moments fling better physically and emotionally.', q.options = '[{"prefix": "A", "content": "tedious", "itemUuid": "cloze-english2-real-2020-1-A"}, {"prefix": "B", "content": "pleasant", "itemUuid": "cloze-english2-real-2020-1-B"}, {"prefix": "C", "content": "instructive", "itemUuid": "cloze-english2-real-2020-1-C"}, {"prefix": "D", "content": "tricky", "itemUuid": "cloze-english2-real-2020-1-D"}]' WHERE q.subject_id = 10 AND q.source_year = 2020 AND q.source_question_no = 1 AND q.deleted = b'0';
