UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2021/q1-title.html" data-fallback="It’s not difficult to set targets for staff. It is much harder, 1 ​ , to understand their negative consequences. Most work-related behaviors have multiple components. 2 ​ one and t"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "therefore", "itemUuid": "cloze-english2-real-2021-1-A"}, {"prefix": "B", "content": "however", "itemUuid": "cloze-english2-real-2021-1-B"}, {"prefix": "C", "content": "again", "itemUuid": "cloze-english2-real-2021-1-C"}, {"prefix": "D", "content": "moreover", "itemUuid": "cloze-english2-real-2021-1-D"}]' AS JSON)) WHERE q.subject_id = 10 AND q.source_year = 2021 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2021/q1-title.html" data-fallback="It’s not difficult to set targets for staff. It is much harder, 1 ​ , to understand their negative consequences. Most work-related behaviors have multiple components. 2 ​ one and t"></div>', q.title_text = 'It’s not difficult to set targets for staff. It is much harder, 1 ​ , to understand their negative consequences. Most work-related behaviors have multiple components. 2 ​ one and the others become distorted. Travel on a London bus and you’ll 3 ​ see how this works with drivers. Watch people get on and show their tickets. Are they carefully inspected? Never. Do people get on without paying? Of course! Are there inspectors to 4 ​ that people have paid? Possibly, but very few. And people who run for the bus? They are 5 ​ . How about jumping lights? Buses do so almost as frequently as cyclists. Why? Because the target is 6 ​ . People complained that buses were late and infrequent. 7 ​ , the number of buses and bus lanes were increased, and drivers were 8 ​ or punished according to the time they took. And drivers hit these targets. But they 9 ​ hit cyclists. If the target was changed to safety, you would get more inspectors and more sensitive pricing. If the criterion changed to 10 ​ you would have more 11 ​ drivers who obeyed traffic laws. But both these criteria would be at the expense of time. There is another 12 ​ : people became immensely inventive in hitting targets. Have you 13 ​ that you can leave on a flight an hour late but still arrive on time? Tailwinds? Of course not! Airlines have simply changed the time a 14 ​ is meant to take. A one-hour flight is now billed as a two-hour flight. The 15 ​ of the story is simple. Most jobs are multidimensional, with multiple criteria. Choose one criterion and you may well 16 ​ others. Everything can be done faster and made cheaper, but there is a 17 ​ . Setting targets can and does have unforeseen negative consequences. This is not an argument against target-setting. But it is an argument for exploring consequences first. All good targets should have multiple criteria 18 ​ critical factors such as time, money, quality and customer feedback. The trick is not only to 19 ​ just one or even two dimensions of the objective, but also to understand how to help people better 20 ​ the objective.', q.options = '[{"prefix": "A", "content": "therefore", "itemUuid": "cloze-english2-real-2021-1-A"}, {"prefix": "B", "content": "however", "itemUuid": "cloze-english2-real-2021-1-B"}, {"prefix": "C", "content": "again", "itemUuid": "cloze-english2-real-2021-1-C"}, {"prefix": "D", "content": "moreover", "itemUuid": "cloze-english2-real-2021-1-D"}]' WHERE q.subject_id = 10 AND q.source_year = 2021 AND q.source_question_no = 1 AND q.deleted = b'0';
