UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2022/q1-title.html" data-fallback="Harlan Coben believes that if you’re a writer, you’ll find the time; and that if you can’t find the time, then writing isn’t a priority and you’re not a writer. For him, writing is"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "difficult", "itemUuid": "cloze-english2-real-2022-1-A"}, {"prefix": "B", "content": "normal", "itemUuid": "cloze-english2-real-2022-1-B"}, {"prefix": "C", "content": "steady", "itemUuid": "cloze-english2-real-2022-1-C"}, {"prefix": "D", "content": "pleasant", "itemUuid": "cloze-english2-real-2022-1-D"}]' AS JSON)) WHERE q.subject_id = 10 AND q.source_year = 2022 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2022/q1-title.html" data-fallback="Harlan Coben believes that if you’re a writer, you’ll find the time; and that if you can’t find the time, then writing isn’t a priority and you’re not a writer. For him, writing is"></div>', q.title_text = 'Harlan Coben believes that if you’re a writer, you’ll find the time; and that if you can’t find the time, then writing isn’t a priority and you’re not a writer. For him, writing is a 1 ​ job, a job like any other. He has 2 ​ it with plumbing, pointing out that a plumber doesn’t wake up and say that he can’t work with pipes today. 3 ​ , like most writers these days, you’re holding down a job to pay the bills, it’s not 4 ​ to find the time to write. But it’s not impossible. It requires determination and single - mindedness. 5 ​ that most bestselling authors began writing when they were doing other things to earn a living. And today, even writers who are fairly 6 ​ often have to do other work to 7 ​ their writing income. As Harlan Coben has suggested it’s a 8 ​ of priorities. To make writing a priority, you’ll have to 9 ​ Some of your day - to - day activities and some things you really enjoy. Depending on your 10 ​ and your lifestyle, that might mean spending less time watching television or listening to music, though some people can write 11 ​ they listen to music. You might have to 12 ​ the amount of exercise or sport you do. You’ll have to make social media an 13 ​ activity rather than a daily, time - consuming 14 ​ . There’ll probably have to be less socializing with your friends and less time with your family. It’s a 15 ​ learning curve, and it won’t always make you popular. There’s just one thing you should try to keep at least some time for, 16 ​ your writing and that’s reading. Any writer needs to read as much and as widely as they can; it’s the one 17 ​ supporter - Something you can’t do without. Time is finite. The older you get, the 18 ​ it seems to go. We need to use it as carefully and as 19 ​ as we can, that means prioritizing out activities so that we spend most time on the things we really want to do. If you are a writer, that means— 20 ​ —writing.', q.options = '[{"prefix": "A", "content": "difficult", "itemUuid": "cloze-english2-real-2022-1-A"}, {"prefix": "B", "content": "normal", "itemUuid": "cloze-english2-real-2022-1-B"}, {"prefix": "C", "content": "steady", "itemUuid": "cloze-english2-real-2022-1-C"}, {"prefix": "D", "content": "pleasant", "itemUuid": "cloze-english2-real-2022-1-D"}]' WHERE q.subject_id = 10 AND q.source_year = 2022 AND q.source_question_no = 1 AND q.deleted = b'0';
