UPDATE t_text_content tc JOIN t_question q ON q.info_text_content_id = tc.id SET tc.content = JSON_SET(tc.content, '$.titleContent', CAST(JSON_QUOTE('<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2025/q1-title.html" data-fallback="There are many understandable reasons why you might find it difficult to ask for help when you need it. Psychologists have been interested in this 1 ​ for decades, not least becaus"></div>') AS JSON), '$.questionItemObjects', CAST('[{"prefix": "A", "content": "illusion", "itemUuid": "cloze-english2-real-2025-1-A"}, {"prefix": "B", "content": "discussion", "itemUuid": "cloze-english2-real-2025-1-B"}, {"prefix": "C", "content": "tradition", "itemUuid": "cloze-english2-real-2025-1-C"}, {"prefix": "D", "content": "question", "itemUuid": "cloze-english2-real-2025-1-D"}]' AS JSON)) WHERE q.subject_id = 10 AND q.source_year = 2025 AND q.source_question_no = 1 AND q.deleted = b'0';
UPDATE t_question q SET q.title = '<div class="question-html-ref" data-src="question-html/csgraduates/english2-real-2025/q1-title.html" data-fallback="There are many understandable reasons why you might find it difficult to ask for help when you need it. Psychologists have been interested in this 1 ​ for decades, not least becaus"></div>', q.title_text = 'There are many understandable reasons why you might find it difficult to ask for help when you need it. Psychologists have been interested in this 1 ​ for decades, not least because people’s widespread 2 ​ to ask for help has led to some high - profile failures. Asking for help takes 3 ​ . It involves communicating a need on your part—there’s something you can’t do. 4 ​ , you’re broadcasting your own weaknesses, which can be 5 ​ . You might worry about coming across as incompetent. You might have 6 ​ about losing control of whatever it is you’re asking for help with. 7 ​ someone starts to help, perhaps they’ll take over, or get credit for your earlier efforts. Yet another 8 ​ that you might be worried about is being a nuisance or 9 ​ the person you go to for help. If you struggle with low self - esteem, you might find it especially difficult to 10 ​ for help because you have the added worry of the other person 11 ​ your request. You might see such refusals as implying something 12 ​ about the status of your relationship with them. To 13 ​ these difficulties, try to remind yourself that everyone needs help sometimes. Nobody knows everything and can do everything all by themselves. And while you might 14 ​ coming across as incompetent, there’s actually research that shows that advice - seekers are 15 ​ as more competent, not less. Perhaps most encouraging of all is a paper from 2022 by researchers at Stanford University, in California, that involved a mix of contrived help - seeking interactions and asking people to 16 ​ times they’d sought help in the past. The findings showed that help - seekers generally underestimate how 17 ​ other people will be to help and how good it’ll make the help - giver feel (for most people, having the chance to help someone is highly 18 ​ ). So, bear all this in mind the next time you need to ask for help. 19 ​ , take care over who you ask and when you ask them. And if someone can’t help right now, avoid taking it personally. They might just be too 20 ​ , or they might not feel confident about their ability to help.', q.options = '[{"prefix": "A", "content": "illusion", "itemUuid": "cloze-english2-real-2025-1-A"}, {"prefix": "B", "content": "discussion", "itemUuid": "cloze-english2-real-2025-1-B"}, {"prefix": "C", "content": "tradition", "itemUuid": "cloze-english2-real-2025-1-C"}, {"prefix": "D", "content": "question", "itemUuid": "cloze-english2-real-2025-1-D"}]' WHERE q.subject_id = 10 AND q.source_year = 2025 AND q.source_question_no = 1 AND q.deleted = b'0';
